import{_ as i,o as t,c as s,a3 as a}from"./chunks/framework.vDgOMd_y.js";const k=JSON.parse('{"title":"kimi Command","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/kimi-command.md","filePath":"en/reference/kimi-command.md"}'),o={name:"en/reference/kimi-command.md"};function n(d,e,l,r,h,p){return t(),s("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/reference/kimi-command.md for this page in Markdown format</div><h1 id="kimi-command" tabindex="-1"><code>kimi</code> Command <a class="header-anchor" href="#kimi-command" aria-label="Permalink to &quot;`kimi` Command&quot;">​</a></h1><p><code>kimi</code> is the main command for Kimi Code CLI, used to start an interactive session in the terminal. Running it without any arguments opens a new session in the current working directory; combined with different flags, you can resume a previous session, skip approvals, start in Plan mode, or load Skills from a custom directory.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [options]</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">subcomman</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [options]</span></span></code></pre></div><h2 id="main-command-options" tabindex="-1">Main Command Options <a class="header-anchor" href="#main-command-options" aria-label="Permalink to &quot;Main Command Options&quot;">​</a></h2><p>All flags are optional — run <code>kimi</code> directly to enter an interactive session:</p><table tabindex="0"><thead><tr><th>Option</th><th>Short</th><th>Description</th></tr></thead><tbody><tr><td><code>--version</code></td><td><code>-V</code></td><td>Print the version number and exit</td></tr><tr><td><code>--help</code></td><td><code>-h</code></td><td>Show help information and exit</td></tr><tr><td><code>--session [id]</code></td><td><code>-S</code></td><td>Resume a session. With an ID, opens that session directly; without an ID, enters an interactive selector</td></tr><tr><td><code>--continue</code></td><td><code>-c</code></td><td>Continue the most recent session in the current working directory, without specifying an ID manually</td></tr><tr><td><code>--model &lt;model&gt;</code></td><td><code>-m</code></td><td>Specify a model alias for this launch. When omitted, new sessions use <code>default_model</code> from the config file</td></tr><tr><td><code>--prompt &lt;prompt&gt;</code></td><td><code>-p</code></td><td>Run a single prompt non-interactively and stream the Assistant output to stdout. This mode does not open the TUI</td></tr><tr><td><code>--output-format &lt;format&gt;</code></td><td></td><td>Set the non-interactive output format; supports <code>text</code> and <code>stream-json</code>. Can only be used with <code>--prompt</code>; defaults to <code>text</code></td></tr><tr><td><code>--yolo</code></td><td><code>-y</code></td><td>Auto-approve regular tool calls, skipping approval requests</td></tr><tr><td><code>--auto</code></td><td></td><td>Start with auto permission mode; tool approvals are handled automatically and the Agent will not ask the user questions</td></tr><tr><td><code>--plan</code></td><td></td><td>Start a new session in Plan mode — the AI will prioritize read-only tools for exploration and planning</td></tr><tr><td><code>--skills-dir &lt;dir&gt;</code></td><td></td><td>Load Skills from the specified directory, replacing the automatically discovered user and project directories. Can be repeated</td></tr><tr><td><code>--agent &lt;name&gt;</code></td><td></td><td>Start a new session with the specified agent as the main Agent. Cannot be combined with <code>--session</code>/<code>--continue</code></td></tr><tr><td><code>--agent-file &lt;path&gt;</code></td><td></td><td>Load a custom agent from a Markdown file for the new session and select it. Cannot be repeated or combined with <code>--agent</code>, <code>--session</code>, or <code>--continue</code></td></tr><tr><td><code>--add-dir &lt;dir&gt;</code></td><td></td><td>Add an extra workspace directory for this session. Relative paths resolve against the current working directory. Can be repeated</td></tr></tbody></table><p><code>-r</code> / <code>--resume</code> is a hidden alias for <code>--session</code>; <code>--yes</code> and <code>--auto-approve</code> are hidden aliases for <code>--yolo</code> and are not shown in help output.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>--yolo</code> skips human approval for regular tool calls, including file writes and shell command execution. Use it only in trusted working directories. Plan mode exit approval is not bypassed by <code>--yolo</code>; <code>Bash</code> inside Plan mode is handled under the regular allow rules.</p></div><h3 id="flag-conflict-rules" tabindex="-1">Flag Conflict Rules <a class="header-anchor" href="#flag-conflict-rules" aria-label="Permalink to &quot;Flag Conflict Rules&quot;">​</a></h3><p>The following combinations are rejected at startup:</p><ul><li><code>--continue</code> and <code>--session</code> are mutually exclusive — both mean &quot;resume a previous session&quot;</li><li><code>--yolo</code> and <code>--auto</code> are mutually exclusive — the two permission modes cannot be combined</li><li><code>--prompt</code> cannot be used with <code>--yolo</code>, <code>--auto</code>, or <code>--plan</code> — non-interactive mode uses <code>auto</code> permission by default</li><li><code>--output-format</code> can only be used together with <code>--prompt</code></li></ul><p>When resuming a session, you can override its saved permission or plan mode by adding <code>--auto</code>, <code>--yolo</code>, or <code>--plan</code>. For example, <code>kimi --continue --auto</code> resumes the latest session and switches it to auto permission mode.</p><h2 id="common-usage" tabindex="-1">Common Usage <a class="header-anchor" href="#common-usage" aria-label="Permalink to &quot;Common Usage&quot;">​</a></h2><p>Start a new session directly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span></span></code></pre></div><p>Pick up where you left off (automatically finds the most recent session in the current directory):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --continue</span></span></code></pre></div><p>Choose from the session history list, or specify a known ID directly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 01HZ...XYZ</span></span></code></pre></div><p>Skip approval prompts — suitable for batch tasks that are known to be safe:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yolo</span></span></code></pre></div><p>Let the Agent handle everything autonomously, without asking the user questions:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --auto</span></span></code></pre></div><p>Read the code and produce an implementation plan before making any file changes:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --plan</span></span></code></pre></div><h3 id="custom-skills-directories" tabindex="-1">Custom Skills Directories <a class="header-anchor" href="#custom-skills-directories" aria-label="Permalink to &quot;Custom Skills Directories&quot;">​</a></h3><p>There are two ways to specify Skills directories, with different semantics:</p><ul><li><p><strong><code>--skills-dir &lt;dir&gt;</code></strong> (CLI flag): <strong>Replaces</strong> the automatically discovered user and project directories for this launch only. Can be repeated to stack multiple directories:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skills-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/team-skills</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skills-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./local-skills</span></span></code></pre></div></li><li><p><strong><code>extra_skill_dirs</code></strong> (<code>config.toml</code>): <strong>Adds</strong> directories on top of the automatically discovered ones, taking effect permanently. Suitable for configuring team-shared Skills. See <a href="./../customization/skills.html">Agent Skills</a>.</p></li></ul><h3 id="custom-agents" tabindex="-1">Custom Agents <a class="header-anchor" href="#custom-agents" aria-label="Permalink to &quot;Custom Agents&quot;">​</a></h3><p><code>--agent</code> and <code>--agent-file</code> select which agent drives a new session, in both print mode (<code>kimi -p</code>) and the interactive TUI:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reviewer</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reviewer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Review the changes on this branch&quot;</span></span></code></pre></div><p><code>--agent-file</code> registers a single agent file at the highest priority for this launch only and selects it; the flag cannot be repeated, and <code>--agent</code> and <code>--agent-file</code> are mutually exclusive. Both flags only apply when starting a new session — neither can be combined with <code>--session</code>/<code>--continue</code>, because the agent is bound at session creation and resuming restores the bound agent automatically. The selection is fixed at the session&#39;s first bind and cannot be switched later; in the TUI the flags bind only the startup session, and a session created later in the same process (for example via <code>/new</code>) starts with the default agent. See <a href="./../customization/agents.html#custom-agents">Agents and Sub-Agents</a> for the agent file format and discovery directories.</p><h2 id="non-interactive-execution" tabindex="-1">Non-Interactive Execution <a class="header-anchor" href="#non-interactive-execution" aria-label="Permalink to &quot;Non-Interactive Execution&quot;">​</a></h2><p>When running a single prompt in a script or CI environment, use <code>-p</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Summarize the current repository status&quot;</span></span></code></pre></div><p>Output uses a transcript style: thinking content and Assistant text are both prefixed with <code>• </code>, and wrapped lines are indented by two spaces. Assistant text goes to stdout; thinking, tool progress, and &quot;resuming session&quot; notices go to stderr. In <code>-p</code> mode, no human approval is requested — regular tool calls are handled under the <code>auto</code> permission policy, while static deny rules remain in effect.</p><p>Temporarily switch the model:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kimi-code/kimi-for-coding</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Explain the latest diff&quot;</span></span></code></pre></div><p>When you need to parse output programmatically, use the <code>stream-json</code> format — each line on stdout is a JSON object:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;List changed files&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stream-json</span></span></code></pre></div><p>In <code>stream-json</code> mode, regular replies produce an Assistant message; when the model calls a tool, an Assistant message with <code>tool_calls</code> is emitted first, followed by the corresponding Tool message, then subsequent Assistant messages. Thinking content is not written to JSONL; tool progress and &quot;resuming session&quot; notices are still written to stderr.</p><h2 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;Subcommands&quot;">​</a></h2><p><code>kimi</code> provides the following subcommands: <code>login</code> (non-interactive login), <code>acp</code> (ACP IDE mode), <code>web</code> (run the local REST/WebSocket/web service in the foreground and open the web UI), <code>doctor</code> (validate configuration files), <code>export</code> (export a session), <code>migrate</code> (migrate legacy data), <code>upgrade</code> (check for updates), and <code>provider</code> (manage providers).</p><h3 id="kimi-login" tabindex="-1"><code>kimi login</code> <a class="header-anchor" href="#kimi-login" aria-label="Permalink to &quot;`kimi login`&quot;">​</a></h3><p>Log in to Kimi Code OAuth via the RFC 8628 device-code flow, without entering the TUI. The command issues a device authorization request, prints the verification URL and user code to stderr, then polls until the browser-side authorization is complete. The generated token is written to the same local location as TUI <code>/login</code> and is loaded automatically the next time <code>kimi</code> starts.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>This subcommand has no flags. Press <code>Ctrl-C</code> at any time during polling to cancel; the exit code is <code>1</code> on cancellation or failure, and <code>0</code> on success.</p><h3 id="kimi-acp" tabindex="-1"><code>kimi acp</code> <a class="header-anchor" href="#kimi-acp" aria-label="Permalink to &quot;`kimi acp`&quot;">​</a></h3><p>Switch Kimi Code CLI to ACP (Agent Client Protocol) mode, communicating with an IDE via JSON-RPC over stdin/stdout so the editor can directly drive kimi&#39;s sessions and tool calls. You typically do not need to run this manually — the IDE starts it as a subprocess entry point. For configuration, see <a href="./../guides/ides.html">Using in IDEs</a>; for technical details, see the <a href="./kimi-acp.html">kimi acp reference</a>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acp</span></span></code></pre></div><h3 id="kimi-web" tabindex="-1"><code>kimi web</code> <a class="header-anchor" href="#kimi-web" aria-label="Permalink to &quot;`kimi web`&quot;">​</a></h3><p>Run the local Kimi server in the foreground of the current terminal — a single process that exposes the REST + WebSocket API and serves the web UI from the same origin — and open the web UI in the default browser once it is ready. The command stays attached to the terminal and shuts down cleanly on <code>SIGINT</code> / <code>SIGTERM</code> (e.g. <code>Ctrl-C</code>).</p><p>When the server is running, <code>GET /openapi.json</code> returns the REST OpenAPI document and <code>GET /asyncapi.json</code> returns the local WebSocket AsyncAPI document.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # run the server in the foreground and open the browser</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-open</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # don&#39;t open the browser</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 58628</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # pick a specific bind port</span></span></code></pre></div><p>Multiple instances can share one home directory: each registers itself under <code>~/.kimi-code/server/instances/</code>, and a busy port is retried with <code>port + 1</code> (58628, 58629, …).</p><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--port &lt;port&gt;</code></td><td>Bind port; defaults to <code>58627</code>; a busy port is retried with <code>+1</code></td></tr><tr><td><code>--host [host]</code></td><td>Bind host; omit for <code>127.0.0.1</code> (this machine only), pass a bare <code>--host</code> for <code>0.0.0.0</code> (all interfaces)</td></tr><tr><td><code>--allowed-host &lt;host...&gt;</code></td><td>Extra Host header values allowed through the DNS-rebinding check; repeatable or comma-separated</td></tr><tr><td><code>--log-level &lt;level&gt;</code></td><td>Enable server logs at the selected level; omitted by default</td></tr><tr><td><code>--debug-endpoints</code></td><td>Mount <code>/api/v1/debug/*</code> routes (off by default)</td></tr><tr><td><code>--dangerous-bypass-auth</code></td><td>Disable bearer-token auth on all REST and WebSocket routes so the web UI connects without a token; only for trusted networks or behind an authenticating proxy</td></tr><tr><td><code>--no-open</code></td><td>Do not open the browser once the server is ready</td></tr></tbody></table><p><code>kimi web</code> binds to local loopback only by default and prints the bearer token in the startup banner; the web UI authenticates automatically via the <code>#token=</code> URL fragment.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The <code>kimi server</code> command tree is deprecated: any <code>kimi server …</code> invocation (including all legacy subcommands) only prints a deprecation notice and exits with code 1 — use <code>kimi web</code> instead. The one exception is <code>kimi server kill</code>, which stays functional for stopping servers started by a version before 0.28.0. The notice will be removed in the next major version of Kimi Code.</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><code>--dangerous-bypass-auth</code> disables authentication entirely. Anyone who can reach the port gets full access to your sessions, filesystem, and shell. Only use it on a trusted network or behind your own authenticating reverse proxy, and stop the server with <code>Ctrl+C</code> when you are done.</p></div><h4 id="kimi-server-kill" tabindex="-1"><code>kimi server kill</code> <a class="header-anchor" href="#kimi-server-kill" aria-label="Permalink to &quot;`kimi server kill`&quot;">​</a></h4><p>Deprecated — only stops a server started by a version before 0.28.0. Those versions could leave a background server behind, recorded in the legacy single-instance lock at <code>~/.kimi-code/server/lock</code>; the command first tries <code>POST /api/v1/shutdown</code> for a graceful exit, then signals the recorded pid with SIGTERM, escalating to SIGKILL when needed, and removes the lock file once the process is confirmed dead. Servers started by <code>kimi web</code> run in the foreground — stop them with <code>Ctrl+C</code> instead.</p><h4 id="kimi-web-rotate-token" tabindex="-1"><code>kimi web rotate-token</code> <a class="header-anchor" href="#kimi-web-rotate-token" aria-label="Permalink to &quot;`kimi web rotate-token`&quot;">​</a></h4><p>Generate a new persistent bearer token (written to <code>~/.kimi-code/server.token</code>); the previous token stops working immediately. The token is shared by the whole home directory, so every running instance picks the new one up on its next auth check — no restart needed.</p><h3 id="kimi-doctor" tabindex="-1"><code>kimi doctor</code> <a class="header-anchor" href="#kimi-doctor" aria-label="Permalink to &quot;`kimi doctor`&quot;">​</a></h3><p>Validate <code>config.toml</code> and <code>tui.toml</code> without starting the TUI or modifying either file. By default, the command checks the files under <code>KIMI_CODE_HOME</code> (or <code>~/.kimi-code</code> when the environment variable is unset). Missing default files are reported as skipped because built-in defaults can apply.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>kimi doctor</code></td><td>Validate the default <code>config.toml</code> and <code>tui.toml</code></td></tr><tr><td><code>kimi doctor config [path]</code></td><td>Validate only <code>config.toml</code>, using <code>path</code> instead of the default file when provided</td></tr><tr><td><code>kimi doctor tui [path]</code></td><td>Validate only <code>tui.toml</code>, using <code>path</code> instead of the default file when provided</td></tr></tbody></table><p>When an explicit path is passed, the file must exist. The command exits with <code>0</code> when all checked files are valid or skipped, and <code>1</code> when any requested file is missing or invalid.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check the default config files</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check only the default runtime config</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check a candidate TUI config before replacing the live config</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tui</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tui.toml</span></span></code></pre></div><h3 id="kimi-export" tabindex="-1"><code>kimi export</code> <a class="header-anchor" href="#kimi-export" aria-label="Permalink to &quot;`kimi export`&quot;">​</a></h3><p>Package a session into a ZIP file for sharing, archiving, or submitting bug reports.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [sessionId] [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Parameter / Option</th><th>Short</th><th>Description</th></tr></thead><tbody><tr><td><code>sessionId</code></td><td></td><td>The ID of the session to export. When omitted, the most recent session in the current working directory is automatically selected and requires confirmation</td></tr><tr><td><code>--output &lt;path&gt;</code></td><td><code>-o</code></td><td>Output ZIP file path. When omitted, writes to a default filename in the current directory</td></tr><tr><td><code>--yes</code></td><td><code>-y</code></td><td>Skip the confirmation prompt for the default session and export directly</td></tr><tr><td><code>--no-include-global-log</code></td><td></td><td>Do not include the global diagnostic log. Included by default</td></tr></tbody></table><p>The export contains all files in the target session directory. The global diagnostic log (<code>~/.kimi-code/logs/kimi-code.log</code>) is included by default because it may contain events from other sessions or projects; add <code>--no-include-global-log</code> if you do not want to share it.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export the most recent session in the current directory, skipping confirmation</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export a specific session to a custom path</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 01HZ...XYZ</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./bug-report.zip</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exclude the global diagnostic log</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 01HZ...XYZ</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./bug-report.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-include-global-log</span></span></code></pre></div><h3 id="kimi-migrate" tabindex="-1"><code>kimi migrate</code> <a class="header-anchor" href="#kimi-migrate" aria-label="Permalink to &quot;`kimi migrate`&quot;">​</a></h3><p>Migrate local data from a legacy kimi-cli installation to kimi-code, including session history and configuration files. Runs entirely interactively, guiding you through the full process.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><p>For full migration instructions, see <a href="./../guides/migration.html">Migrating from kimi-cli</a>.</p><h3 id="kimi-upgrade" tabindex="-1"><code>kimi upgrade</code> <a class="header-anchor" href="#kimi-upgrade" aria-label="Permalink to &quot;`kimi upgrade`&quot;">​</a></h3><p>Immediately check for the latest version and display an update prompt; exits after you make a selection. <code>kimi update</code> is an alias for this command.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>For global npm, pnpm, yarn, bun, and macOS / Linux native installations, <code>kimi upgrade</code> shows update options; selecting <code>Install update now</code> runs the corresponding foreground install command. When the current installation method cannot be upgraded automatically (e.g., Windows native installation), the manual update command is printed instead.</p><h3 id="kimi-vis" tabindex="-1"><code>kimi vis</code> <a class="header-anchor" href="#kimi-vis" aria-label="Permalink to &quot;`kimi vis`&quot;">​</a></h3><p>Launch the session visualizer in your browser to inspect a session as it unfolds. The command starts an in-process server pointed at your local sessions, prints the URL, opens your browser, and keeps running until you press <code>Ctrl-C</code>.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [sessionId] [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Parameter / Option</th><th>Description</th></tr></thead><tbody><tr><td><code>sessionId</code></td><td>Open the visualizer directly to this session. When omitted, it opens the home view listing your sessions</td></tr><tr><td><code>--port &lt;number&gt;</code></td><td>Port to bind. By default an available port is picked automatically</td></tr><tr><td><code>--host &lt;host&gt;</code></td><td>Host to bind. Default: <code>127.0.0.1</code></td></tr><tr><td><code>--no-open</code></td><td>Do not open the browser automatically; just print the URL</td></tr></tbody></table><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start the visualizer and open the browser at the home view</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vis</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Open directly to a specific session</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vis</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 01HZ...XYZ</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Bind a fixed port and host without opening a browser (e.g. on a remote host)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vis</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8123</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-open</span></span></code></pre></div><h3 id="kimi-provider" tabindex="-1"><code>kimi provider</code> <a class="header-anchor" href="#kimi-provider" aria-label="Permalink to &quot;`kimi provider`&quot;">​</a></h3><p>Manage providers in the shell — the non-interactive equivalent of <code>/provider</code> in the TUI. Suitable for scripted deployments, CI initialization, and one-line setup on a new machine.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">actio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [options]</span></span></code></pre></div><p>Five actions are available:</p><h4 id="kimi-provider-add-url" tabindex="-1"><code>kimi provider add &lt;url&gt;</code> <a class="header-anchor" href="#kimi-provider-add-url" aria-label="Permalink to &quot;`kimi provider add &lt;url&gt;`&quot;">​</a></h4><p>Bulk-import all providers from a custom registry (<code>api.json</code>). The command fetches the registry, creates a <code>[providers.&lt;id&gt;]</code> and <code>[models.&lt;alias&gt;]</code> entry for each item, and writes <code>source</code> metadata so the TUI refreshes providers and models from the same registry URL automatically on next startup.</p><table tabindex="0"><thead><tr><th>Parameter / Option</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;url&gt;</code></td><td>Registry URL</td></tr><tr><td><code>--api-key &lt;key&gt;</code></td><td>Bearer token for accessing the registry. Falls back to the <code>KIMI_REGISTRY_API_KEY</code> environment variable if not provided; required</td></tr></tbody></table><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.example.com/v1/models/api.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --api-key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> YOUR_KEY</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or via environment variable (suitable for CI / .envrc)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">KIMI_REGISTRY_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">YOUR_KEY</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.example.com/v1/models/api.json</span></span></code></pre></div><p>If a provider ID already exists, it is removed and re-created. The default model is not set automatically; you can select one later with <code>-m</code> or <code>/model</code> in the TUI.</p><h4 id="kimi-provider-remove-providerid" tabindex="-1"><code>kimi provider remove &lt;providerId&gt;</code> <a class="header-anchor" href="#kimi-provider-remove-providerid" aria-label="Permalink to &quot;`kimi provider remove &lt;providerId&gt;`&quot;">​</a></h4><p>Remove the specified provider and all its model aliases. If the removed provider is the one referenced by <code>default_model</code>, <code>default_model</code> is also cleared.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kohub</span></span></code></pre></div><h4 id="kimi-provider-list" tabindex="-1"><code>kimi provider list</code> <a class="header-anchor" href="#kimi-provider-list" aria-label="Permalink to &quot;`kimi provider list`&quot;">​</a></h4><p>Print each configured provider on a separate line, including type, model count, and source. Add <code>--json</code> to output the raw <code>providers</code> and <code>models</code> tables for programmatic processing.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.providers | keys&#39;</span></span></code></pre></div><h4 id="kimi-provider-catalog-list-providerid" tabindex="-1"><code>kimi provider catalog list [providerId]</code> <a class="header-anchor" href="#kimi-provider-catalog-list-providerid" aria-label="Permalink to &quot;`kimi provider catalog list [providerId]`&quot;">​</a></h4><p>Browse the public <a href="https://models.dev/" target="_blank" rel="noreferrer">models.dev</a> model catalog without modifying any configuration. Without an argument, lists all providers along with their protocol type and model count; with a <code>providerId</code>, lists all models under that provider along with their context window and capabilities. If the catalog URL cannot be reached, a built-in snapshot of the catalog is used instead.</p><table tabindex="0"><thead><tr><th>Parameter / Option</th><th>Description</th></tr></thead><tbody><tr><td><code>[providerId]</code></td><td>Optional — the provider ID to inspect</td></tr><tr><td><code>--filter &lt;substring&gt;</code></td><td>Case-insensitive substring filter on ID or name</td></tr><tr><td><code>--url &lt;url&gt;</code></td><td>Override the catalog URL; defaults to <code>https://models.dev/api.json</code></td></tr><tr><td><code>--json</code></td><td>Output matching entries as JSON</td></tr></tbody></table><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> anthropic</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> anthropic</span></span></code></pre></div><h4 id="kimi-provider-catalog-add-providerid" tabindex="-1"><code>kimi provider catalog add &lt;providerId&gt;</code> <a class="header-anchor" href="#kimi-provider-catalog-add-providerid" aria-label="Permalink to &quot;`kimi provider catalog add &lt;providerId&gt;`&quot;">​</a></h4><p>Import a known provider directly from the catalog by ID. The protocol type, base URL, and model information are all supplied by the catalog — only an API key is required. Vendors whose protocol the catalog does not declare (e.g. xai, openrouter, and other vendor-specific SDKs) are imported as OpenAI-compatible and the output notes the guess; when the catalog provides no usable endpoint, <code>--base-url</code> is required. Proprietary protocols (e.g. Amazon Bedrock) cannot be imported. When the public catalog is unreachable, the import uses the built-in snapshot, so it still works offline or in blocked networks.</p><table tabindex="0"><thead><tr><th>Parameter / Option</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;providerId&gt;</code></td><td>Provider ID in the catalog, e.g., <code>anthropic</code>, <code>openai</code></td></tr><tr><td><code>--api-key &lt;key&gt;</code></td><td>Provider API key. Falls back to <code>KIMI_REGISTRY_API_KEY</code> if not provided; required</td></tr><tr><td><code>--default-model &lt;modelId&gt;</code></td><td>Optional — set <code>default_model</code> to <code>&lt;providerId&gt;/&lt;modelId&gt;</code> after import</td></tr><tr><td><code>--base-url &lt;url&gt;</code></td><td>Override the catalog endpoint; required when the catalog declares none (or only an env placeholder)</td></tr><tr><td><code>--url &lt;url&gt;</code></td><td>Override the catalog URL; defaults to <code>https://models.dev/api.json</code></td></tr></tbody></table><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> anthropic</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Browse available models first</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provider</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> anthropic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --api-key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sk-ant-...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --default-model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-opus-4-7</span></span></code></pre></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./slash-commands.html">Slash Commands</a> — Quick reference for control commands in the interactive TUI</li><li><a href="./../configuration/config-files.html">Configuration Files</a> — Persistent configuration for <code>default_model</code>, permission mode, and other startup parameters</li><li><a href="./../customization/skills.html">Agent Skills</a> — Skill file format for directories loaded via <code>--skills-dir</code></li><li><a href="./../customization/agents.html">Agents and Sub-Agents</a> — Built-in sub-agents, custom agent files, and main Agent selection via <code>--agent</code></li></ul>',114)])])}const g=i(o,[["render",n]]);export{k as __pageData,g as default};
